package com.elitedarkkaiser.nubialy;
import org.junit.Test;import static org.junit.Assert.*;
public class SettingsStyleTest {
 @Test public void boundsAndRoundTrip(){var s=SettingsStyle.DEFAULT;assertTrue(s.valid());assertEquals(s,SettingsStyle.decode(s.encode()));assertEquals(s.with(0,1).with(12,302),SettingsStyle.decode(s.with(0,1).with(12,302).encode()));assertNull(SettingsStyle.decode(s.encode()+",0"));assertFalse(s.with(0,2).valid());assertFalse(s.with(2,0x77112233).valid());assertFalse(s.with(7,41).valid());assertFalse(s.with(8,20).valid());assertFalse(s.with(9,131).valid());assertFalse(s.with(10,121).valid());assertFalse(s.with(11,25).valid());assertFalse(s.with(12,99).valid());}
 @Test public void followsOnlyAppliedSettingsAndPreservesCustomSizing(){var applied=SurfaceStyle.STOCK.withQsTheme(SurfaceStyle.QsTheme.STOCK.with(1,0xff112233).with(4,0xffabcdef));var s=SettingsStyle.DEFAULT.with(0,1).with(12,300).with(8,90).resolve(applied,false);assertEquals(0xff112233,s.card());assertEquals(0xffabcdef,s.title());assertEquals(90,s.rowHeight());assertEquals(1,s.layout());assertEquals(0,s.surface());assertEquals(0xfffcfcff,SettingsStyle.DEFAULT.with(1,1).resolve(applied,true).card());var custom=SettingsStyle.DEFAULT.with(1,3).with(3,0xff334455);assertEquals(custom,custom.resolve(applied,false));}
}
